          border: '1px solid #f1f5f9',
          borderRadius: '8px',
          backgroundColor: '#f8fafc',
          padding: '10px'
        }}>
          {state.options.map((opt, i) => {
            const barHeight = 30;
            const barSpacing = 25;
            const startY = 40;
            const y = startY + i * (barHeight + barSpacing);
            const barWidth = totalVotes === 0 ? 0 : (opt.votes / totalVotes) * 400;

            return (
              <g key={opt.id}>
                {/* Option label */}
                <text
                  x="10"
                  y={y - 6}
                  fill="#475569"
                  style={{ fontSize: '13px', fontWeight: '600' }}
                >
                  {opt.text}
                </text>

                {/* Bar background */}
                <rect
                  x="10"
                  y={y}
                  width="400"
                  height={barHeight}
                  rx="4"
                  ry="4"
                  fill="#e2e8f0"
                />

                {/* Bar */}
                <rect
                  class="chart-bar"
                  data-option-id={opt.id}
                  x="10"
                  y={y}
                  width={barWidth}
                  height={barHeight}
                  rx="4"
                  ry="4"
                  fill="#3b82f6"
                  style={{ transition: 'width 0.3s ease' }}
                />

                {/* Vote count */}
                <text
                  class="vote-count"
                  data-option-id={opt.id}
                  x={barWidth + 20}
                  y={y + 20}
                  fill="#1e293b"
                  style={{ fontSize: '14px', fontWeight: '700' }}
                >
                  {opt.votes}
                </text>
              </g>
            );
          })}
        </svg>
      </div>

      {state.errorMessage && (
        <div style={{
          padding: '12px 16px',
          backgroundColor: '#fef2f2',
          border: '1px solid #fca5a5',
          borderRadius: '6px',
          color: '#b91c1c',
          marginBottom: '20px',
          fontSize: '14px',
          fontWeight: '500'
        }}>
          {state.errorMessage}
        </div>
      )}

      <div style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '12px'
      }}>
        {state.options.map((opt) => (
          <button
            key={opt.id}
            class="vote-button"
            data-option-id={opt.id}
            onClick$={() => castVote(opt.id)}
            style={{
              padding: '12px 16px',
              fontSize: '15px',
              fontWeight: '600',
              color: '#ffffff',
              backgroundColor: '#3b82f6',
              border: 'none',
              borderRadius: '8px',
              cursor: 'pointer',
              transition: 'background-color 0.2s ease',
              textAlign: 'left'
            }}
          >
            Vote for {opt.text}
          </button>
        ))}
      </div>
    </div>
  );
});

import type { RequestHandler } from '@builder.io/qwik-city';
import { getOptions, castVoteTransaction, getPoll } from '../../../../db';

export const onPost: RequestHandler = async (event) => {
  const pollId = event.params.id;

  // 1. Check if the poll exists
  const poll = getPoll(pollId);
  if (!poll) {
    event.json(404, { error: 'Poll or option not found' });
    return;
  }

  // 2. Parse request body
  let optionId: any;
  try {
    const body = await event.request.json() as { optionId?: any };
    optionId = body?.optionId;
  } catch {
    event.json(400, { error: 'Invalid option ID' });
    return;
  }

  if (optionId === undefined || optionId === null || typeof optionId !== 'number' || isNaN(optionId)) {
    event.json(400, { error: 'Invalid option ID' });
    return;
  }

  // 3. Get client IP
  const xForwardedFor = event.request.headers.get('x-forwarded-for');
  let ip = '127.0.0.1';
  if (xForwardedFor) {
    const parts = xForwardedFor.split(',');
    if (parts[0]) {
      ip = parts[0].trim();
    }
  } else if (event.clientConn?.ip) {
    ip = event.clientConn.ip;
  }

  const now = Date.now();

  // 4. Perform vote inside transaction
  const result = castVoteTransaction(pollId, optionId, ip, now);

  if (result.error === 'rate_limit') {
    event.json(429, { error: 'Rate limit exceeded' });
    return;
  }

  if (result.error === 'not_found') {
    event.json(404, { error: 'Poll or option not found' });
    return;
  }

  // 5. Fetch updated options
  const options = getOptions(pollId);
  const votesObj: Record<string, number> = {};
  for (const opt of options) {
    votesObj[String(opt.id)] = opt.votes;
  }

  event.json(200, {
    success: true,
    votes: votesObj,
  });
};
